 for m in MILESTONES:write(f'milestone-{m["number"]}.html',page(f'Milestone {m["number"]}','<div class="document-wrap">'+head(f'Milestone {m["number"]} · after Unit {m["unit"]}',m['title'],'A snapshot of the same project record.')+milestone_body(m)+f'<p><a href="{unit_url(m["unit"])}#step-3">Return to the Finish step →</a></p></div>'))
 write('finish.html',page('Finish and handoff','<div class="document-wrap">'+head('Bring the evidence together','What will happen next?','Finish with a usable solution, an honest recommendation, and a clear handoff.')+'<p data-progress>0 of 12 units marked complete</p><p>Study markers help you navigate. Review your actual evidence against the <a href="project.html">five milestones</a> before calling the project complete.</p><ol><li>Let someone use the artifact and locate its instructions.</li><li>Show the baseline, observed task, revision, retest, and limits.</li><li>Explain intended impact, resource needs, release readiness, supported adoption, and the next decision.</li><li>Name the operating owner, human review, exceptions, and stopping conditions.</li></ol>'+notes('final-handoff','My recommendation:\nEvidence and limits:\nOwner and handoff location:\nNext test or decision:')+'<div class="button-row"><button class="button" type="button" data-backup>Save final workbook backup</button><a href="index.html">Review the learning path</a></div><p class="muted">Self-study completion is not a credential. In a taught offering, follow the published submission and feedback process.</p></div>'))
 template='# Building AI Solutions — project record\n\nCourse by Majid Memari\nLearner/team:\nContext and version date:\n\n'
 for m in MILESTONES:template+=f'## {m["number"]}. {m["title"]}\n\n'+''.join('[ ] '+x+'\n' for x in m['checklist'])+'\nEvidence links:\nDecision:\nAssumptions and limitations:\nChanges since last snapshot:\n\n'
 write('downloads/project-record.txt',template)
 write('downloads/cedar-desk-packet.txt','\n'.join(line.rstrip() for line in re.sub(r'<[^>]+>',' ',COURSE_CASE_HTML).splitlines())+'\n')
 redirects={'course.html':'index.html','guide.html':'resources.html','projects.html':'project.html','toolkit.html':'resources.html#workbook','discussions.html':'project.html','business-paths.html':'index.html','partner-challenge.html':'project.html','venture-studio.html':'unit-09.html','labs/index.html':'../unit-06.html#step-1'}
