 for name,target in redirects.items():write(name,f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url={esc(target)}"><title>Continue · Building AI Solutions</title></head><body><p>The course now follows one twelve-unit path. <a href="{esc(target)}">Continue to the current lesson →</a></p></body></html>')
 with zipfile.ZipFile(OUT/'downloads/course-site.zip','w',zipfile.ZIP_DEFLATED) as z:
  for path in sorted(OUT.rglob('*')):
   if path.is_file() and path.suffix!='.zip':
    relative=path.relative_to(OUT)
    if relative.as_posix()=='resources.html':
     portable=path.read_text().replace('href="downloads/course-site.zip"','href="https://www.majidmemari.com/teaching/ai-solutions/downloads/course-site.zip"')
     z.writestr(str(relative),portable)
    else:z.write(path,relative)
 print(f'Built {len(UNITS)} units and {len(MILESTONES)} milestones in {OUT}')
